package com.assetsphere.modules.workspace;
import java.util.*; import org.springframework.stereotype.Component; import com.assetsphere.modules.common.*; import com.assetsphere.modules.workspace.domain.*;
@Component public class WorkspaceAuthorization { private final WorkspaceMemberRepository members; public WorkspaceAuthorization(WorkspaceMemberRepository members){this.members=members;} public boolean isMember(UUID workspaceId,UUID userId){return members.findByWorkspaceIdAndUserId(workspaceId,userId).map(WorkspaceMember::isActive).orElse(false);} public boolean hasAnyRole(UUID workspaceId,UUID userId,WorkspaceRole... roles){return members.findByWorkspaceIdAndUserId(workspaceId,userId).filter(WorkspaceMember::isActive).map(member->Arrays.asList(roles).contains(member.getRole())).orElse(false);} public void requireMembership(UUID w,UUID u){if(!isMember(w,u))throw new ResourceNotFoundException("Workspace not found");} public void requireAnyRole(UUID w,UUID u,WorkspaceRole... r){if(!hasAnyRole(w,u,r))throw new AuthorizationDeniedException("Insufficient workspace permission");} }
